const fs = require('fs');
const input = { ...$input.first().json };

const inputPath = '/tmp/odoo_06_raw_push_input.json';
fs.writeFileSync(inputPath, JSON.stringify(input), 'utf8');

return [{
  json: {
    ok: true,
    input_path: inputPath,
    snapshot_id: input.snapshot_id,
    message: 'Input JSON written for Stage 06 raw GitHub push',
  },
}];

const item = $input.first().json;

if (item.exitCode !== undefined && Number(item.exitCode) !== 0) {
  throw new Error(
    `Stage 06 raw GitHub push failed (exit ${item.exitCode}). stderr: ${item.stderr || ''}`,
  );
}

const stdout = String(item.stdout || '').trim();
if (!stdout) {
  throw new Error(
    `Stage 06 raw GitHub push returned empty stdout. stderr: ${item.stderr || ''}`,
  );
}

const lastLine = stdout.split(/\r?\n/).filter(Boolean).pop();

try {
  return [{ json: JSON.parse(lastLine) }];
} catch (e) {
  throw new Error(
    `Could not parse Stage 06 stdout as JSON: ${e.message}. stdout starts: ${stdout.slice(0, 500)}`,
  );
}
